from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def calc_total(items: list[dict]) -> str:
    total = Decimal('0')
    for item in items:
        price = item.get('price')
        qty = item.get('qty')

        if not (isinstance(price, str) and isinstance(qty, int)):
            raise ValueError("Each item must have 'price' as a string and 'qty' as an integer.")

        try:
            price_decimal = Decimal(price)
        except InvalidOperation:
            raise ValueError(f"Invalid price value: {price}")

        if not price_decimal.is_finite() or price_decimal < 0:
            raise ValueError(f"Price must be a nonnegative finite decimal: {price}")

        if qty < 0:
            raise ValueError(f"Quantity must be a nonnegative integer: {qty}")

        total += price_decimal * qty

    return f'{total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)}'

