class EventLedger:
    def __init__(self):
        self.events = {}
        self.balance = Decimal('0.00')

    def apply(self, event_id: str, amount: str) -> bool:
        if not event_id:
            raise ValueError("Event ID must be nonempty.")

        try:
            amount_decimal = Decimal(amount)
        except (InvalidOperation, TypeError):
            raise ValueError("Amount must be a valid number.")

        if not amount_decimal.is_finite() or amount_decimal < 0:
            raise ValueError("Amount must be a nonnegative finite number.")

        if event_id in self.events:
            if self.events[event_id] == amount_decimal:
                return False  # Exact duplicate, do nothing and return False
            else:
                raise ValueError("Event ID reused with a different amount.")

        self.events[event_id] = amount_decimal
        self.balance += amount_decimal
        return True  # New event, added to the ledger and returned True

    def total(self) -> str:
        return str(self.balance.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

