import time
from typing import Callable, TypeVar, Any

T = TypeVar('T')


def retry_call(operation: Callable[[], T], *, attempts: int = 3, base_delay: float = 0.1, sleep: Callable[[float], None] = time.sleep) -> T:
    """
    Call the operation with no arguments and return its result.
    Retry only on ConnectionError and TimeoutError, up to a maximum of 'attempts' calls.
    Before each retry, wait for base_delay * 2 ** retry_index seconds.
    No sleep after the final failure; propagate the original exception.

    :param operation: A callable that takes no arguments and returns a value.
    :param attempts: The maximum number of attempts (must be a positive integer).
    :param base_delay: The base delay in seconds before the first retry (must be finite and non-negative).
    :param sleep: A callable that takes a single argument (seconds) and is used for sleeping between retries.
    :return: The result of the operation if successful.
    :raises ValueError: If 'attempts' is not a positive integer or 'base_delay' is not finite and non-negative.
    :raises Exception: The original exception from the operation if all attempts fail.
    """
    if not isinstance(attempts, int) or attempts <= 0:
        raise ValueError("'attempts' must be a positive integer.")
    if not (isinstance(base_delay, (int, float)) and base_delay >= 0 and not math.isinf(base_delay)):
        raise ValueError("'base_delay' must be a finite, non-negative number.")

    for i in range(attempts):
        try:
            return operation()
        except (ConnectionError, TimeoutError) as e:
            if i < attempts - 1:
                sleep(base_delay * 2 ** i)
            else:
                raise e from None

